// auto assumes a braced initializer is a std::initializer_list

auto x1 = { 1, 2, 3 }; // type is std::initializer_list<int>
auto x2 = { 10 };       // type is std::initializer_list<int>, not int!

void takes_int(int i) {}
void takes_list(std::initializer_list<int> il) {}

// takes_int(x2);  // Error: x2 is not an int
takes_list(x2);   // OK
